import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.7R1OEGYz.js";const c=JSON.parse('{"title":"Chat integrations","description":"","frontmatter":{},"headers":[],"relativePath":"chat.md","filePath":"chat.md","lastUpdated":null}'),n={name:"chat.md"};function h(o,s,l,r,p,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="chat-integrations" tabindex="-1">Chat integrations <a class="header-anchor" href="#chat-integrations" aria-label="Permalink to &quot;Chat integrations&quot;">​</a></h1><p>Telegram and Signal notify you when a session waits for input or finishes, and let you reply and approve permission prompts from your phone. Both are part of the free core — Slack is an enterprise feature.</p><p>Long answers are split across several messages. Permission prompts expire after about 30 minutes; after that, answer in the web terminal.</p><h2 id="one-replica-only" tabindex="-1">One replica only <a class="header-anchor" href="#one-replica-only" aria-label="Permalink to &quot;One replica only {#one-replica-only}&quot;">​</a></h2><p>Both integrations require <code>backend.replicas=1</code>. Telegram&#39;s <code>getUpdates</code> and the Signal receive socket each allow exactly one consumer, and a second poller would fight the first for every update. The chart refuses to render otherwise:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: chat.telegram/chat.signal require backend.replicas=1</span></span></code></pre></div><p>The backend default is <strong>2</strong>, so enabling chat halves it. That is a real availability trade-off: no failover, and a brief gap during rolling updates. Nothing is lost when the pod restarts — Telegram buffers updates by offset for roughly 24 hours.</p><h2 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h2><h3 id="_1-create-the-bot" tabindex="-1">1. Create the bot <a class="header-anchor" href="#_1-create-the-bot" aria-label="Permalink to &quot;1. Create the bot&quot;">​</a></h3><p>Talk to <a href="https://t.me/BotFather" target="_blank" rel="noreferrer">@BotFather</a>, create a bot, and copy the token. It looks like <code>123456789:AAF…</code>.</p><h3 id="_2-enable-it" tabindex="-1">2. Enable it <a class="header-anchor" href="#_2-enable-it" aria-label="Permalink to &quot;2. Enable it&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-then-reuse-values</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat.telegram.enabled=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set-string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat.telegram.botToken=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">toke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend.replicas=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p>Use <code>--set-string</code> for the token: it contains a colon, and <code>--set</code> would try to be clever about it.</p><p>Without Helm, the equivalent environment variables are <code>Chat__Telegram__Enabled=true</code> and <code>Chat__Telegram__BotToken=&lt;token&gt;</code>.</p><h3 id="verify-telegram" tabindex="-1">3. Verify it works <a class="header-anchor" href="#verify-telegram" aria-label="Permalink to &quot;3. Verify it works {#verify-telegram}&quot;">​</a></h3><p>The backend is quiet on success, so &quot;no errors in the log&quot; is the expected state and not much of a signal. Ask Telegram instead — the backend publishes the bot&#39;s command menu at startup, so if the commands are registered, the connection works end to end:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.telegram.org/bot&lt;token&gt;/getMyCommands&quot;</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;result&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;link&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Link this chat to your AgentHub account&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sessions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;List sessions in this chat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;use&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Choose the session for plain replies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Show session status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]}</span></span></code></pre></div><p>An empty <code>result</code> means the backend never reached Telegram. Check the log for the giveaway line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/agenthub-backend</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> telegram</span></span></code></pre></div><p><code>Telegram long polling not started (no bot token / disabled)</code> means the configuration did not arrive. A <code>Conflict: terminated by other getUpdates request</code> warning means two pollers are running — expected for a few seconds during a rolling update, a problem if it persists (check <code>backend.replicas</code>).</p><h3 id="_4-link-your-account" tabindex="-1">4. Link your account <a class="header-anchor" href="#_4-link-your-account" aria-label="Permalink to &quot;4. Link your account&quot;">​</a></h3><p>Each user links themselves: <strong>Settings → Notifications → Telegram → Generate link code</strong>, then open the <code>t.me</code> deep link, or send <code>/link &lt;code&gt;</code> to the bot directly.</p><h3 id="per-session-forum-topics" tabindex="-1">Per-session forum topics <a class="header-anchor" href="#per-session-forum-topics" aria-label="Permalink to &quot;Per-session forum topics&quot;">​</a></h3><p>Optional, and worth it if you run several sessions at once. Create a Telegram group, turn on <strong>Topics</strong>, add the bot as an admin with the <strong>Manage topics</strong> permission, and send <code>/link &lt;code&gt;</code> in the group. Every session then gets its own topic.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Everyone in a linked group can reply to sessions and approve permission prompts.</p></div><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>/sessions</code></td><td>List sessions in this chat</td></tr><tr><td><code>/use &lt;tag&gt;</code></td><td>Route plain replies to that session</td></tr><tr><td><code>!status</code></td><td>Show session status</td></tr></tbody></table><p>Plain messages are typed into the active session&#39;s terminal.</p><h2 id="signal" tabindex="-1">Signal <a class="header-anchor" href="#signal" aria-label="Permalink to &quot;Signal&quot;">​</a></h2><h3 id="_1-enable-it" tabindex="-1">1. Enable it <a class="header-anchor" href="#_1-enable-it" aria-label="Permalink to &quot;1. Enable it&quot;">​</a></h3><p>This deploys <a href="https://github.com/bbernhard/signal-cli-rest-api" target="_blank" rel="noreferrer">signal-cli-rest-api</a> with a persistent volume for the account keys:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-then-reuse-values</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat.signal.enabled=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set-string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat.signal.number=+15551234567</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend.replicas=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><h3 id="_2-register-the-sender-number" tabindex="-1">2. Register the sender number <a class="header-anchor" href="#_2-register-the-sender-number" aria-label="Permalink to &quot;2. Register the sender number&quot;">​</a></h3><p>Once, via port-forward: <code>POST /v1/register/&lt;number&gt;</code> followed by <code>/v1/register/&lt;number&gt;/verify/&lt;token&gt;</code> with the SMS or voice code. You can also link it as a secondary device by QR code. The exact commands are in the comment block of <a href="https://github.com/open-agenthub/open-agenthub/blob/main/helm/open-agenthub/templates/signal-cli.yaml" target="_blank" rel="noreferrer"><code>templates/signal-cli.yaml</code></a>.</p><p>The image tag is pinned on purpose — the account registration and keys live on the PVC, so check the signal-cli-rest-api release notes for migration steps before bumping it.</p><h3 id="_3-link-your-account" tabindex="-1">3. Link your account <a class="header-anchor" href="#_3-link-your-account" aria-label="Permalink to &quot;3. Link your account&quot;">​</a></h3><p>Each user enters their number under <strong>Settings → Notifications → Signal</strong> and confirms the six-digit code sent via Signal.</p><h3 id="reply-routing" tabindex="-1">Reply routing <a class="header-anchor" href="#reply-routing" aria-label="Permalink to &quot;Reply routing&quot;">​</a></h3><p><strong>Quote</strong> a session message to answer that session; plain replies go to the newest session, or the one picked with <code>!use</code>. React 👍/👎 on a permission prompt to allow or deny, and quote-reply <code>always</code> for allow-always. Commands: <code>!sessions</code>, <code>!use &lt;tag&gt;</code>, <code>!status</code>.</p><h2 id="desktop-notifications" tabindex="-1">Desktop notifications <a class="header-anchor" href="#desktop-notifications" aria-label="Permalink to &quot;Desktop notifications&quot;">​</a></h2><p>A browser notification when a session waits for input or finishes. Enable it per device under <strong>Settings → Notifications</strong> — no cluster configuration needed.</p>`,42)])])}const g=i(n,[["render",h]]);export{c as __pageData,g as default};
